-- ============================================================
-- Share the Spoils: wiring
-- ============================================================
--
-- TODO.md: "Improved Revive Pet (Renamed to Share the Spoils) (3, 1):
-- Redesigned. Killing an enemy that grants experience or honor has a 50/100%
-- chance to increase the mana returned by Aspect of the Viper by 500% for 10
-- seconds. (2 ranks) (Icon should be aspect of the viper icon)"
--
-- SpellIconID 2227 is Aspect of the Viper's own icon (read off 34074), used on
-- both talent ranks and on the buff so the three read as one thing.
--
-- All three retail effects are wiped: they were a Revive Pet cast-time cut, a
-- cost cut and a returned-health bonus, none of which survives the redesign.
-- Effect1 becomes a plain SPELL_AURA_PROC_TRIGGER_SPELL pointing at 200748.
--
-- ProcFlags 2 = PROC_FLAG_KILL, documented in SpellMgr.h:111 as "Kill target
-- (in most cases need XP/Honor reward)" -- which is the requirement's wording
-- almost verbatim, so no extra XP check is needed in script.
--
-- TWO rows, one per rank, because the 50/100% split lives in spell_proc.Chance
-- and spell_proc is keyed by spell id.  A negative all-ranks row could not carry
-- two different chances.
--
-- AttributesMask stays 0: a kill event is not a triggered spell cast, so the
-- Aura::IsProcTriggeredOnEvent filter never applies (asserted by
-- src/test/server/game/Spells/SpellProcTriggeredFilterTest.cpp).
DELETE FROM `spell_proc` WHERE `SpellId` IN (24443, 19575);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(24443, 0, 0, 0, 0, 0, 2, 0, 2, 0, 0, 0, 0, 50, 0, 0),
(19575, 0, 0, 0, 0, 0, 2, 0, 2, 0, 0, 0, 0, 100, 0, 0);

-- The amplification is a SpellScript on 34075, NOT an AuraScript on 34074.
--
-- Core's spell_hun_ascpect_of_the_viper (spell_hunter.cpp:388-425) computes the
-- mana itself and hands it to 34075 via CastCustomSpell(SPELLVALUE_BASE_POINT0).
-- It consults exactly one modifier -- glyph 56851 -- so a second aura on 34074
-- is invisible to it.  Registering a competing AuraScript there would have to
-- energize a second time rather than scale the first, which double-counts
-- against the glyph.  Multiplying 34075's own effect value composes with the
-- glyph and needs no core change.
DELETE FROM `spell_script_names` WHERE `spell_id` = 34075 AND `ScriptName` = 'spell_hun_viper_spoils';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(34075, 'spell_hun_viper_spoils');
